jv jv_string_vfmt(const char* fmt, va_list ap) {
  int size = 1024;
  while (1) {
    char* buf = jv_mem_alloc(size);
    va_list ap2;
    va_copy(ap2, ap);
    int n = vsnprintf(buf, size, fmt, ap2);
    va_end(ap2);
    /*
     * NOTE: here we support old vsnprintf()s that return -1 because the
     * buffer is too small.
     */
    if (n >= 0 && n < size) {
      jv ret = jv_string_sized(buf, n);
      jv_mem_free(buf);
      return ret;
    } else {
      jv_mem_free(buf);
      if (n > 0) {
        /* Standard compliant: n is needed size - 1 */
        size = n + 1;
      } else {
        /* Legacy vsnprintf(): grow exponentially but reasonably */
        if (size > INT_MAX / 2)
          size = INT_MAX;
        else
          size *= 2;
      }
    }
  }
}

